function commerceStreetPoint(street) {
  const idx = street && street.indices && street.indices[0];
  return idx && locations[idx - 1] ? locations[idx - 1] : null;
}

function haversineMeters(a, b) {
  if (!a || !b) return Infinity;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const s = Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371000 * Math.asin(Math.sqrt(s));
}

function buildCommercesIndices(selectedIds) {
  const ids = Array.isArray(selectedIds) ? selectedIds : [];
  const remaining = commerceStreets.filter((s) => ids.includes(s.id));
  if (!remaining.length) {
    return circuits.commerces ? circuits.commerces.slice() : [1];
  }
  const gp = locations[0];
  const ordered = [];
  let cur = gp;
  const pool = remaining.slice();
  while (pool.length) {
    let bestI = 0;
    let bestD = Infinity;
    pool.forEach((street, i) => {
      street.indices.forEach((idx) => {
        const loc = locations[idx - 1];
        const d = haversineMeters(cur, loc);
        if (d < bestD) {
          bestD = d;
          bestI = i;
        }
      });
    });
    const street = pool.splice(bestI, 1)[0];
    if (street.entire && street.indices.length === 2) {
      const a = locations[street.indices[0] - 1];
      const b = locations[street.indices[1] - 1];
      if (haversineMeters(cur, a) <= haversineMeters(cur, b)) {
        ordered.push(street.indices[0], street.indices[1]);
        cur = b;
      } else {
        ordered.push(street.indices[1], street.indices[0]);
        cur = a;
      }
    } else {
      street.indices.forEach((idx) => ordered.push(idx));
      cur = locations[street.indices[street.indices.length - 1] - 1];
    }
  }
  return [1, ...ordered, 1];
}

